#include <functional>
#include <iostream>
#include <map>
#include <queue>
#include <string>
#include <vector>

using Graph = std::map<std::string, std::vector<std::pair<std::string, int>>>;

int main()
{
    Graph roads{};
    auto road{[&](const std::string& a, const std::string& b, int km) {
        roads[a].push_back({b, km});
        roads[b].push_back({a, km});
    }};
    road("Ashby", "Bray", 4);
    road("Bray", "Carr", 3);
    road("Carr", "Dunmore", 7);
    road("Ashby", "Dunmore", 20);
    roads["Eston"];
}
